data.query:
query GetDataPointsByType {
  floatDataPoints: dataPoint(
    where: {
      historize: { _eq: true }
      enabled: { _eq: true }
      dataType: { _eq: "float" }
      asset: { status: { _eq: "Active" } }
    }
    first: 10000
  ) {
    edges {
      node {
        id
        dataType
        frequency
        setPoint
        upperLimit
        lowerLimit
        tolerance
        precision
      }
    }
  }
  
  integerDataPoints: dataPoint(
    where: {
      historize: { _eq: true }
      enabled: { _eq: true }
      dataType: { _eq: "integer" }
      asset: { status: { _eq: "Active" } }
    }
    first: 10000
  ) {
    edges {
      node {
        id
        frequency
        setPoint
        upperLimit
        lowerLimit
        tolerance
        precision
      }
    }
  }
  
  booleanDataPoints: dataPoint(
    where: {
      historize: { _eq: true }
      enabled: { _eq: true }
      dataType: { _eq: "boolean" }
      asset: { status: { _eq: "Active" } }
    }
    first: 10000
  ) {
    edges {
      node {
        id
        name
        frequency
      }
    }
  }
  
  stringDataPoints: dataPoint(
    where: {
      historize: { _eq: true }
      enabled: { _eq: true }
      dataType: { _eq: "string" }
      asset: { status: { _eq: "Active" } }
    }
    first: 10000
  ) {
    edges {
      node {
        id
        frequency
      }
    }
  }
}

