/**
 * Calculate simple UTC 5-minute window for all datapoints
 * Window: (now - 5 minutes) to now
 */

var config = {
  frequencySeconds: 300, // 5 minutes
  anomaly: { enabled: true, probability: 0.02 }
};

// Calculate UTC window - subtract 5 minutes from now
var now = new Date();
var windowEnd = now.toISOString();
var windowStartMs = now.getTime() - (config.frequencySeconds * 1000);
var windowStart = new Date(windowStartMs).toISOString();

console.log('=== TIME WINDOW (UTC) ===');
console.log('Start: ' + windowStart);
console.log('End:   ' + windowEnd);
console.log('Duration: ' + config.frequencySeconds + ' seconds');

// Pass through original query data + add window context
return {
  floatDataPoints: $.floatDataPoints,
  integerDataPoints: $.integerDataPoints,
  booleanDataPoints: $.booleanDataPoints,
  stringDataPoints: $.stringDataPoints,
  timezone: $.timezone,
  window: {
    start: windowStart,
    end: windowEnd,
    timezone: 'UTC',
    anomalyEnabled: config.anomaly.enabled,
    anomalyProb: config.anomaly.probability
  }
};

