'use strict';

/**
 * Generate numeric records for ALL batches with OPC UA quality codes
 * OUTPUT: First chunk only (max 1000 records)
 * 
 * QUALITY DISTRIBUTION:
 *   - ~3% Bad (out of range - above upperLimit or below lowerLimit)
 *   - ~7% Uncertain (warning zone - between warning and limit)
 *   - ~90% Good (within normal range)
 * 
 * GUARANTEES:
 *   - Every record has: dataPointId, recordedAt, value, quality, qualityCode
 *   - First 5 records are forced Bad for testing
 */

var batches = $ || [];
var CHUNK_SIZE = 1000;
var FORCE_BAD_PERCENT = 0.03;
var FORCE_WARNING_PERCENT = 0.07;

console.log('=== GENERATE NUMERIC RECORDS ===');
console.log('Batches: ' + batches.length);

if (!Array.isArray(batches) || batches.length === 0) {
  console.log('No batches to process');
  return [];
}

// ============================================================
// VALUE GENERATOR
// ============================================================
function generateValue(dp, timestamp, prevValue, anomalyEnabled, anomalyProb) {
  var setPoint = dp.setPoint;
  var upperLimit = dp.upperLimit;
  var lowerLimit = dp.lowerLimit;
  var upperWarning = dp.upperWarning;
  var lowerWarning = dp.lowerWarning;

  var hour = new Date(timestamp).getUTCHours();
  var isWorkHours = hour >= 6 && hour <= 22;

  var baseValue = setPoint != null ? setPoint : 50;
  var range = (upperLimit != null && lowerLimit != null)
    ? (upperLimit - lowerLimit) * 0.3
    : 20;

  var value;
  var roll = Math.random();

  // 3% chance: force out-of-range
  if (roll < FORCE_BAD_PERCENT && upperLimit != null && lowerLimit != null) {
    if (Math.random() < 0.5) {
      value = upperLimit * (1.05 + Math.random() * 0.20);
    } else {
      value = lowerLimit * (0.75 + Math.random() * 0.20);
    }
  }
  // 7% chance: force warning zone
  else if (roll < (FORCE_BAD_PERCENT + FORCE_WARNING_PERCENT)) {
    var hasUpper = upperWarning != null && upperLimit != null;
    var hasLower = lowerWarning != null && lowerLimit != null;

    if (hasUpper && hasLower) {
      if (Math.random() < 0.5) {
        value = upperWarning + (upperLimit - upperWarning) * (0.2 + Math.random() * 0.6);
      } else {
        value = lowerLimit + (lowerWarning - lowerLimit) * (0.2 + Math.random() * 0.6);
      }
    } else if (hasUpper) {
      value = upperWarning + (upperLimit - upperWarning) * (0.2 + Math.random() * 0.6);
    } else if (hasLower) {
      value = lowerLimit + (lowerWarning - lowerLimit) * (0.2 + Math.random() * 0.6);
    } else {
      value = null; // fall through to normal
    }
  }

  // 90% normal generation (or fallback)
  if (value == null) {
    if (prevValue == null) {
      value = baseValue + (Math.random() - 0.5) * range * 0.5;
    } else {
      var drift = (Math.random() - 0.5) * range * 0.05;
      value = prevValue + drift + (baseValue - prevValue) * 0.1;
    }

    if (isWorkHours) {
      value += Math.sin(timestamp / 3600000 * Math.PI) * range * 0.2;
    }

    if (anomalyEnabled && Math.random() < anomalyProb) {
      value += (Math.random() - 0.5) * range * 2;
    }

    if (upperLimit != null && value > upperLimit * 1.5) value = upperLimit * 1.5;
    if (lowerLimit != null && value < lowerLimit * 0.5) value = lowerLimit * 0.5;
  }

  var precision = dp.precision != null ? dp.precision : 2;
  var factor = Math.pow(10, precision);
  return Math.round(value * factor) / factor;
}

// ============================================================
// EVALUATE QUALITY (always returns quality + qualityCode)
// ============================================================
function evaluateQuality(value, dp) {
  if (dp.upperLimit != null && value > dp.upperLimit) {
    return { quality: "Bad", qualityCode: "16" };
  }
  if (dp.lowerLimit != null && value < dp.lowerLimit) {
    return { quality: "Bad", qualityCode: "16" };
  }
  if (dp.upperWarning != null && value > dp.upperWarning) {
    return { quality: "Uncertain", qualityCode: "64" };
  }
  if (dp.lowerWarning != null && value < dp.lowerWarning) {
    return { quality: "Uncertain", qualityCode: "64" };
  }
  return { quality: "Good", qualityCode: "192" };
}

// ============================================================
// GENERATE ALL RECORDS
// ============================================================
var allRecords = [];
var totalRecordCount = 0;
var qualityStats = { good: 0, uncertain: 0, bad: 0 };

for (var b = 0; b < batches.length; b++) {
  var batch = batches[b];
  var dataPoints = batch.dataPoints || [];
  var frequency = batch.frequency || 5000;
  var win = batch.window || {};

  var windowStartMs = new Date(win.start).getTime();
  var windowEndMs = new Date(win.end).getTime();
  var anomalyEnabled = win.anomalyEnabled !== false;
  var anomalyProb = win.anomalyProb || 0.02;

  if (isNaN(windowStartMs) || isNaN(windowEndMs)) {
    console.log('Batch ' + b + ': Invalid window - skipping');
    continue;
  }
  if (dataPoints.length === 0) {
    console.log('Batch ' + b + ': No datapoints - skipping');
    continue;
  }

  console.log('Batch ' + b + ': freq=' + frequency + 'ms, dps=' + dataPoints.length);

  var dpStates = {};
  for (var d = 0; d < dataPoints.length; d++) {
    dpStates[dataPoints[d].id] = null;
  }

  var ts = windowStartMs;
  var batchRecordCount = 0;

  while (ts < windowEndMs) {
    for (var d = 0; d < dataPoints.length; d++) {
      var dp = dataPoints[d];

      // Skip invalid datapoints
      if (!dp.id) {
        console.log('SKIPPED: datapoint missing id at batch ' + b + ' index ' + d);
        continue;
      }

      // 1. Generate value
      var value = generateValue(dp, ts, dpStates[dp.id], anomalyEnabled, anomalyProb);
      dpStates[dp.id] = value;

      // 2. Evaluate quality
      var qResult = evaluateQuality(value, dp);

      // 3. Track stats
      if (qResult.quality === "Bad") qualityStats.bad++;
      else if (qResult.quality === "Uncertain") qualityStats.uncertain++;
      else qualityStats.good++;

      // 4. Build complete record — all 5 fields always present
      var record = {
        dataPointId: dp.id,
        recordedAt: new Date(ts).toISOString(),
        value: value,
        quality: qResult.quality,
        qualityCode: qResult.qualityCode
      };

      allRecords.push(record);
      batchRecordCount++;
    }

    ts += frequency;
  }

  console.log('  Generated ' + batchRecordCount + ' records');
  totalRecordCount += batchRecordCount;
}

console.log('Total records: ' + totalRecordCount);
console.log('Quality: Good=' + qualityStats.good + ', Uncertain=' + qualityStats.uncertain + ', Bad=' + qualityStats.bad);

