// FORCE FIRST 5 RECORDS BAD
// ============================================================
for (var i = 0; i < Math.min(1, allRecords.length); i++) {
  var original = allRecords[i].value;
  allRecords[i].value = original * 10;
  allRecords[i].quality = "Bad";
  allRecords[i].qualityCode = "16";
