function generateValue(name, timestamp, prevValue, anomalyEnabled, anomalyProb) {
  var nameLower = (name || '').toLowerCase();
  var hour = new Date(timestamp).getUTCHours();
  var isWorkHours = hour >= 6 && hour <= 22;
  
  var values;
  var changeProb = 0.05;
  
  if (nameLower.indexOf('mode') >= 0) {
    values = statusSets.mode;
    changeProb = 0.02;
  } else if (nameLower.indexOf('status') >= 0 || nameLower.indexOf('state') >= 0) {
    values = statusSets.operational;
    changeProb = isWorkHours ? 0.08 : 0.02;
  } else if (nameLower.indexOf('health') >= 0 || nameLower.indexOf('condition') >= 0) {
    values = statusSets.health;
    changeProb = 0.03;
  } else if (nameLower.indexOf('process') >= 0 || nameLower.indexOf('phase') >= 0) {
    values = statusSets.process;
    changeProb = isWorkHours ? 0.1 : 0.01;
  } else {
    values = statusSets.operational;
  }
  
  var value;
  var anomalyTriggered = false;
  
  if (prevValue == null || Math.random() < changeProb) {
    if (isWorkHours && values === statusSets.operational) {
      var r = Math.random();
      if (r < 0.7) value = 'Running';
      else if (r < 0.9) value = 'Idle';
      else value = values[Math.floor(Math.random() * values.length)];
    } else if (values === statusSets.health) {
      var r = Math.random();
      if (r < 0.85) value = 'Normal';
      else if (r < 0.95) value = 'Warning';
      else value = values[Math.floor(Math.random() * values.length)];
    } else {
      value = values[Math.floor(Math.random() * values.length)];
    }
  } else {
    value = prevValue;
  }
  
  if (anomalyEnabled && Math.random() < anomalyProb) {
    if (values === statusSets.operational) {
      value = Math.random() < 0.5 ? 'Stopped' : 'Error';
    } else if (values === statusSets.health) {
      value = 'Alarm';
    } else if (values === statusSets.process) {
      value = 'Error';
    }
    anomalyTriggered = true;
  }
  
  return {
    value: value,
    anomalyTriggered: anomalyTriggered
  };
}

