      var quality = null;
      var qualityCode = null;
      
      // Mark fault/error/alarm states with quality codes
      if (result.value === 'Alarm' || result.value === 'Fault' || result.value === 'Error' || result.value === 'Offline') {
        quality = "Bad";
        qualityCode = 16; // Bad - Sensor/Process Failure
      } else if (result.value === 'Warning' || result.anomalyTriggered) {
        quality = "Uncertain";
        qualityCode = 64; // Uncertain
      }
      // else: Good quality (192) - we omit quality fields for normal readings
      
      // ============================================================
      // BUILD RECORD
      // ============================================================
      
      var record = {
        dataPointId: dp.id,
        recordedAt: new Date(ts).toISOString(),
